def _load_embedded(name, blob):
    mod = _types.ModuleType(name)
    mod.__dict__['__name__'] = name
    mod.__dict__['__file__'] = f'<embedded:{name}>'
    _sys.modules[name] = mod
    src = _zlib.decompress(_b64.b85decode(blob.encode('ascii'))).decode('utf-8')
    exec(compile(src, f'<embedded:{name}>', 'exec'), mod.__dict__)
    return mod

_TETSU = _load_embedded('_e22_tetsu_' + _uuid.uuid4().hex, _TETSU_BLOB)
_AURAX = _load_embedded('_e22_aurax_' + _uuid.uuid4().hex, _AURAX_BLOB)

TELEMETRY = {'calls': 0, 'errors': 0, 'market_changed': 0}
_BASE = _TETSU._ADV_PARENT

def _standard(configuration):
    if configuration is None:
        return True
    try:
        for k, v in (
            ('boardSize', 10),
            ('turnsPerDay', 24),
            ('shedCapacity', 100),
            ('maxMarketOrdersPerTurn', 10),
            ('farmHandCostMult', 1),
        ):
            if configuration.get(k, v) != v:
                return False
        if configuration.get('marketParams', None):
            return False
    except Exception:
        return False
    return True

def _future_market(observation, offset=1):
    try:
        step = int(observation['step']) + int(offset)
        if step >= 719:
            return None
        players = _TETSU._IMPL.chassis.players
        native = players.get(int(observation['player'])) if isinstance(players, dict) else None
        route = 2 if step >= 648 else (native or {}).get('route')
        if route is None:
            return None
        action = _TETSU._IMPL.chassis.routes[route][step]
        return action.get('market') if isinstance(action, dict) else None
    except Exception:
        return None

def _update_race_state(observation, action):
    try:
        player = int(observation['player'])
        step = int(observation['step'])
        st = _TETSU._RACE_STATE.get(player)
        if st is not None and st.get('prev_action') is not None and st.get('step') == step:
            st['prev_action'] = action
    except Exception:
        pass

def agent(observation, configuration=None):
    action = _BASE(observation, configuration)
    TELEMETRY['calls'] += 1
    try:
        if isinstance(action, dict) and _standard(configuration):
            market = action.get('market')
            market = list(market) if isinstance(market, list) else []
            new_market = _AURAX.advance_sales(observation, market, _future_market, TELEMETRY)
            if len(new_market) > 1:
                new_market = _AURAX.frontload(observation, new_market, None, TELEMETRY)
            if new_market != market:
                action = dict(action)
                action['market'] = new_market
                TELEMETRY['market_changed'] += 1
        _update_race_state(observation, action)
    except Exception:
        TELEMETRY['errors'] += 1
        _update_race_state(observation, action)
    return action

melon_maxxer = agent
